const raw = $input.first().json.body ?? $input.first().json;
const group = raw.group ?? 'standard';
const event = raw.event ?? 'unknown';
const payload = raw.payload ?? {};
const app = raw.app ?? (event.startsWith('landing.') ? 'landing' : event.startsWith('crm.') ? 'crm' : 'unknown');
const domain = raw.domain ?? 'unknown';
const action = raw.action ?? event.split('.').pop();

const FLOW_MAP = {
  'landing.contact.submitted': 'landing_contact',
  'landing.quote.requested': 'landing_quote',
  'landing.preinscription.created': 'landing_preinscription',
  'crm.candidature.created': 'crm_candidature_create',
  'crm.candidature.status_changed': 'crm_candidature_status',
  'crm.candidature.session.enrolled': 'crm_session_enroll',
  'crm.candidature.exam.recorded': 'crm_exam',
  'crm.candidature.attestation.issued': 'crm_attestation',
  'crm.candidature.parcours.completed': 'crm_parcours_done',
  'crm.candidature.parcours.archived': 'crm_parcours_archive',
  'crm.lead.converted': 'crm_lead_convert',
  'crm.finance.devis.created': 'crm_devis_create',
  'crm.finance.devis.sent': 'crm_devis_sent',
  'crm.finance.devis.accepted': 'crm_devis_accept',
  'crm.finance.payment.recorded': 'crm_payment',
};

const flow = FLOW_MAP[event] ?? 'unknown_event';

return [{
  json: {
    group,
    event,
    app,
    domain,
    action,
    flow,
    emittedAt: raw.emittedAt,
    source: raw.source ?? 'gsms-lms',
    payload,
  }
}];

const item = $input.first().json;
const event = item.event;

// URLs Docker internes — pas de $env (bloqué sur n8n Hostinger)
const GSMS_CRM_URL = 'http://gsms-crm:3001';
// Coller ici le même secret que N8N_WEBHOOK_SECRET sur /opt/gsms/.env
const INTERNAL_SECRET = '';

const CHANNEL_RULES = {
  'landing.contact.submitted': ['email', 'chat'],
  'landing.quote.requested': ['email', 'chat'],
  'landing.preinscription.created': ['email', 'chat'],
  'crm.finance.devis.accepted': ['email', 'chat'],
  'crm.finance.payment.recorded': ['email', 'chat'],
};

const channels = CHANNEL_RULES[event] ?? (event.startsWith('crm.') ? ['chat'] : ['email']);
const crmBase = GSMS_CRM_URL.replace(/\/$/, '');

return [{
  json: {
    ...item,
    channels,
    internalSecret: INTERNAL_SECRET,
    dispatchUrl: `${crmBase}/api/internal/n8n/dispatch`,
    dispatchBody: {
      channels,
      event,
      payload: item.payload ?? {},
      emittedAt: item.emittedAt,
    },
  }
}];
